import os, glob, re, json

# Load grids from session log
d = os.environ.get('RLM_SESSION_DIR', '/tmp')

# Find all jsonl files and check their content
all_files = []
for root, dirs, files in os.walk(d):
    if 'state' in root:
        for f in files:
            if f.endswith('.jsonl'):
                all_files.append(os.path.join(root, f))

print(f"Found {len(all_files)} jsonl files")

# Check for demo content in all files
for f in sorted(all_files):
    with open(f, 'r') as file:
        content = file.read()
        if 'Demo' in content or 'Test input' in content:
            print(f"Content from {f}:")

            # Extract demo/input grids
            pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
            results = {}
            for m in re.finditer(pattern, content):
                k, h, w = m[1], int(m[2]), int(m[3])
                rows = [r.split() for r in content[m.end():].split('\n')[:h]]
                if k not in results and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                    results[k] = [[int(x) for x in r] for r in rows]

            if results:
                for k, v in results.items():
                    print(f"\n{k}:")
                    print(f"  Input: {v[0][:3] if len(v[0]) > 0 else 'empty'}... (size {len(v[0])}x{len(v)})")
                    print(f"  Output: {v[1][:3] if len(v[1]) > 0 else 'empty'}...")

